53		constructor(
54			@ILogService private readonly logService: ILogService,
55			@IInstantiationService private readonly instantiationService: IInstantiationService,
56			@IClaudeSessionStateService private readonly sessionStateService: IClaudeSessionStateService,
57		) {
58			super();
