290		public async invoke(
291			request: vscode.ChatRequest,
292			stream: vscode.ChatResponseStream,
293			yieldRequested: (() => boolean) | undefined,
294			token: vscode.CancellationToken
295		): Promise<void> {
296			if (this._store.isDisposed) {
297				throw new Error('Session disposed');
298			}
299	
300			if (token.isCancellationRequested) {
301				throw new Error('Request was cancelled');
302			}
303	
304			const toolInvocationToken = request.toolInvocationToken;
305			const prompt = await resolvePromptToContentBlocks(request);
306	
307			this._cancelGatewayIdleTimer();
308	
309			// Check if settings files have changed since session started
310			if (this._queryGenerator && await this._settingsChangeTracker.hasChanges()) {
311				this.logService.trace('[ClaudeCodeSession] Settings files changed, restarting session with resume');
312				this._restartSession();
313			}
314	
315			// Check if the set of enabled tools has changed since the last request
316			if (this._queryGenerator && this._hasToolsChanged(request.tools)) {
317				this.logService.trace('[ClaudeCodeSession] Tools changed, restarting session with resume');
318				this._restartSession();
319			}
320			this._snapshotTools(request.tools);
321	
322			// Read current model and permission mode from session state service
323			// Do this BEFORE starting a session so the Options are correct from the start
324			const modelId = this.sessionStateService.getModelIdForSession(this.sessionId);
325			const permissionMode = this.sessionStateService.getPermissionModeForSession(this.sessionId);
326			const effortLevel = this.sessionStateService.getReasoningEffortForSession(this.sessionId);
327	
328			if (effortLevel !== this._currentEffort) {
329				this._currentEffort = effortLevel;
330				// Effort doesn't have a direct setter on the query generator, so we need to restart the session
331				if (this._queryGenerator) {
332					this._restartSession();
333				}
334			}
335			// Update model and permission mode on active session if they changed
336			if (modelId) {
337				await this._setModel(modelId);
338			}
339			await this._setPermissionMode(permissionMode);
340	
341			if (!this._queryGenerator) {
342				await this._startSession(token);
343			}
344	
345			// Add this request to the queue and wait for completion
346			const deferred = new DeferredPromise<void>();
347			const queuedRequest: QueuedRequest = {
348				prompt,
349				stream,
350				toolInvocationToken,
351				token,
352				yieldRequested,
353				messageId: request.id,
354				deferred
355			};
356	
357			this._promptQueue.push(queuedRequest);
358	
359			// If there's a pending prompt request, fulfill it immediately
360			if (this._pendingPrompt) {
361				const pendingPrompt = this._pendingPrompt;
362				this._pendingPrompt = undefined;
363				pendingPrompt.complete(queuedRequest);
364			}
365	
366			return deferred.p;
367		}

